export function validateMigrationRegistry(): {
  isValid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Check for duplicate IDs
  const ids = new Set<string>();
  for (const migration of AVAILABLE_MIGRATIONS) {
    if (ids.has(migration.id)) {
      errors.push(`Duplicate migration ID: ${migration.id}`);
    }
    ids.add(migration.id);
  }

  // Check for duplicate versions
  const versions = new Set<number>();
  for (const migration of AVAILABLE_MIGRATIONS) {
    if (versions.has(migration.version)) {
      errors.push(`Duplicate migration version: ${migration.version}`);
    }
    versions.add(migration.version);
  }

  // Check version ordering
  for (let i = 0; i < AVAILABLE_MIGRATIONS.length - 1; i++) {
    const current = AVAILABLE_MIGRATIONS[i];
    const next = AVAILABLE_MIGRATIONS[i + 1];
    if (current && next && current.version >= next.version) {
      errors.push(
        `Migration order violation: ${current.id} (v${current.version}) should come before ${next.id} (v${next.version})`
      );
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

