/**
 * @fileoverview Payments Webhook Controller
 *
 * Handles payment gateway webhook notifications.
 * This is a PUBLIC endpoint (no auth) but protected by signature verification.
 *
 * Security:
 * - PayU signature verification via IPaymentGateway
 * - Rate limiting to prevent abuse
 * - Raw body access for signature verification
 *
 * Flow:
 * 1. Receive webhook from PayU
 * 2. Verify signature via IPaymentGateway.verifyWebhookSignature()
 * 3. Extract payment status
 * 4. Dispatch CompletePaymentCommand
 * 5. Return acknowledgment
 *
 * TS-TOKEN-TOPUP-001 Faza 0 (DEC20): the `POST /mock` endpoint that used to
 * live here was removed — it was a public, unauthenticated "set payment to
 * COMPLETED" switch (TM-TOPUP-S1, DREAD 14). `PAYMENT_GATEWAY` is bound to
 * `NullPaymentGateway` in every environment until a real, production-safe
 * PayU adapter exists (see `PaymentModule.onModuleInit()`).
 *
 * @module App/API/Payments
 * @since TS-LISTING-FEE-MVP
 */

import {
  Body,
  Controller,
  Headers,
  HttpCode,
  HttpStatus,
  Inject,
  Post,
  RawBodyRequest,
  Req,
} from '@nestjs/common';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import { ICommandBus, Result } from '@vytches/ddd';
import type { Request } from 'express';

import { SkipPermissionCheck } from '@app/shared/infrastructure';
import {
  CompletePaymentCommand,
  PAYMENT_GATEWAY,
  type CompletePaymentResult,
  type IPaymentGateway,
} from '@contexts/payment/application';
import {
  PaymentAlreadyCompletedError,
  PaymentAlreadyFailedError,
  PaymentWebhookProcessingFailedError,
} from '@contexts/payment/domain/errors/payment.errors';
import { ILoggerService, LOGGER_SERVICE } from '@shared/infrastructure/logging';
import { PublicEndpointSchema } from '@shared/response';
import { InternalServerError, ValidationError } from '@shared/response/errors/base-response-error';
import {
  mapPayuStatusToInternal,
  payuWebhookPayloadSchema,
  webhookAcknowledgmentSchema,
  type PayuWebhookPayload,
  type WebhookAcknowledgment,
} from '@shared/validation/schemas/payments';

// ============================================================================
// CONSTANTS
// ============================================================================

/**
 * PayU Signature Header name
 *
 * PayU sends this header with HMAC signature for verification.
 * In MVP mock mode, we accept any signature.
 */
const PAYU_SIGNATURE_HEADER = 'openpayu-signature';

// ============================================================================
// CONTROLLER
// ============================================================================

/**
 * Payments Webhook Controller
 *
 * Handles webhook notifications from payment gateways.
 *
 * Endpoints:
 * - POST /api/payments/webhooks/payu - PayU webhook (production)
 */
@Controller('payments/webhooks')
@ApiTags('Payments Webhooks')
export class PaymentsWebhookController {
  constructor(
    @Inject(ICommandBus) private readonly commandBus: ICommandBus,
    @Inject(PAYMENT_GATEWAY) private readonly paymentGateway: IPaymentGateway,
    @Inject(LOGGER_SERVICE) private readonly logger: ILoggerService
  ) {}

  // ============================================================================
  // PAYU WEBHOOK (PRODUCTION)
  // ============================================================================

  /**
   * PayU Webhook Endpoint
   * POST /api/payments/webhooks/payu
   *
   * Receives payment status notifications from PayU gateway.
   * PUBLIC - No auth, but signature-verified.
   *
   * Security:
   * - Signature verification via IPaymentGateway.verifyWebhookSignature()
   * - Raw body preserved for signature verification
   * - Rate limited
   *
   * @param body - PayU webhook payload
   * @param signature - OpenPayU-Signature header
   * @param req - Raw request for signature verification
   * @returns WebhookAcknowledgment
   */
  @Post('payu')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'PayU webhook notification',
    description: 'Receives payment status updates from PayU. Signature-verified, no auth required.',
  })
  @SkipPermissionCheck()
  @PublicEndpointSchema({
    request: {
      body: payuWebhookPayloadSchema,
    },
    response: {
      schema: webhookAcknowledgmentSchema,
      status: HttpStatus.OK,
      description: 'Webhook acknowledged',
    },
    errors: [ValidationError, InternalServerError],
    options: {
      operationType: 'payment_webhook',
      excludeDefaultErrors: true,
    },
  })
  async handlePayuWebhook(
    @Body() body: PayuWebhookPayload,
    @Headers(PAYU_SIGNATURE_HEADER) signature: string | undefined,
    @Req() req: RawBodyRequest<Request>
  ): Promise<Result<WebhookAcknowledgment>> {
    this.logger.info('[PaymentsWebhook] Received PayU webhook', {
      orderId: body.order?.orderId,
      status: body.order?.status,
      hasSignature: !!signature,
    });

    // 1. Verify signature (for security)
    // NOTE: req.rawBody requires `rawBody: true` in NestFactory.create() (main.ts).
    // A re-serialized JSON body is never byte-identical to the original PayU
    // payload, so there is no safe fallback here — a missing rawBody is an
    // internal configuration error, not something to silently work around.
    if (!req.rawBody) {
      this.logger.error('[PaymentsWebhook] req.rawBody is undefined — rawBody:true misconfigured', {
        orderId: body.order?.orderId,
      });
      return Result.fail(new PaymentWebhookProcessingFailedError(body.order?.orderId ?? 'unknown'));
    }

    const rawBody = req.rawBody.toString();
    const signatureValid = this.paymentGateway.verifyWebhookSignature(rawBody, signature || '');

    if (!signatureValid) {
      this.logger.warn('[PaymentsWebhook] Invalid PayU signature', {
        orderId: body.order?.orderId,
      });
      return Result.fail(new ValidationError('Invalid webhook signature'));
    }

    // 2. Extract payment information
    const externalPaymentId = body.order.orderId;
    const payuStatus = body.order.status;
    const internalStatus = mapPayuStatusToInternal(payuStatus);

    this.logger.debug('[PaymentsWebhook] Processing payment status', {
      externalPaymentId,
      payuStatus,
      internalStatus,
    });

    // 3. Dispatch CompletePaymentCommand
    const command = new CompletePaymentCommand(
      externalPaymentId,
      internalStatus,
      body as unknown as Record<string, unknown>,
      internalStatus === 'FAILED' ? `PayU status: ${payuStatus}` : undefined
    );

    const result = await this.commandBus.execute<
      CompletePaymentCommand,
      Result<CompletePaymentResult>
    >(command);

    if (result.isFailure) {
      // Idempotent duplicate (payment already reached a terminal state via an
      // earlier notification): retrying will never resolve this, so we
      // acknowledge it the same way a fresh success would be acknowledged —
      // this is NOT a failure PayU should retry on.
      const isIdempotentDuplicate =
        result.error instanceof PaymentAlreadyCompletedError ||
        result.error instanceof PaymentAlreadyFailedError;

      if (isIdempotentDuplicate) {
        this.logger.info('[PaymentsWebhook] Idempotent duplicate webhook notification', {
          externalPaymentId,
          errorType: result.error.constructor.name,
        });
        return Result.ok({
          acknowledged: true,
          processedAt: new Date().toISOString(),
        });
      }

      // Any other failure (not-found, repository/outbox errors, unexpected
      // domain rule violations) is NOT known to be unfixable by a retry, so
      // it must surface as a 5xx and let PayU retry — silently swallowing it
      // as 200 (the previous behavior) hid genuine failures (TM-TOPUP-R1).
      // TODO(TS-TOKEN-TOPUP-001 Faza 0, część A2): po dodaniu tabeli
      // payment_gateway_raw_notifications, 2xx ma zależeć od udanego zapisu
      // wiersza, nie tylko od przetworzenia komendy.
      this.logger.error('[PaymentsWebhook] Failed to complete payment', {
        externalPaymentId,
        errorType: result.error.constructor.name,
        error: result.error.message,
      });
      return Result.fail(new PaymentWebhookProcessingFailedError(externalPaymentId));
    }

    this.logger.info('[PaymentsWebhook] Payment completed successfully', {
      externalPaymentId,
      paymentId: result.value.paymentId,
      contextType: result.value.contextType,
      contextEntityId: result.value.contextEntityId,
    });

    return Result.ok({
      acknowledged: true,
      paymentId: result.value.paymentId,
      processedAt: new Date().toISOString(),
    });
  }
}

