29	  async acquireLock(
30	    userId: string,
31	    operationType: SecurityOperationType,
32	    tokenHash: string,
33	    tokenSalt: string,
34	    operationData: Record<string, any>,
35	    metadata?: SecurityOperationMetadata
36	  ): Promise<Result<SecurityOperation, ConcurrentOperationError | LockAcquisitionError>> {
37	    const operationId = AppUtils.getUUID();
38	    const expiresAt = this.calculateExpiration();
