/**
 * @fileoverview Payment Module
 *
 * NestJS module for Payment bounded context.
 * Provides CQRS handlers, repository, gateway, and error mapper.
 *
 * Pattern: VytchesDDD Auto Handler Registration
 * Command/Query handlers auto-registered via @CommandHandler/@QueryHandler decorators.
 *
 * @module Payment
 * @since TS-LISTING-FEE-MVP
 */

import { Inject, Module, type OnModuleInit } from '@nestjs/common';
import { TransactionHost } from '@nestjs-cls/transactional';
import { TransactionalAdapterKysely } from '@nestjs-cls/transactional-adapter-kysely';

import type { Database } from '@shared/database/types/database.types';
import { KyselyEventPersistenceHandler } from '@shared/infrastructure';
import { MetadataStandardsService } from '@shared/infrastructure/logging/metadata';
import { RequestContextService } from '@shared/infrastructure/request-context/request-context.service';
import { EVENT_PERSISTENCE_HANDLER_TOKEN } from '@shared/infrastructure/vytches-ddd/constants';
import { DomainErrorRegistryService } from '@shared/response/services/domain-error-registry.service';
import { ErrorMappingRegistry } from '@shared/response/services/error-mapping-registry.service';

// Application - Commands
import { CompletePaymentHandler, InitiatePaymentHandler } from './application/commands';
// Application - Event Handlers
import { PaymentAuditHandler, PaymentCompletedHandler } from './application/event-handlers';
// Application - Queries
import { GetPaymentStatusHandler } from './application/queries';
// Domain
import type { IPaymentGateway } from './domain/ports';
import { PAYMENT_REPOSITORY } from './domain/repositories/payment.repository';
// Infrastructure - Gateways
import { NullPaymentGateway, PAYMENT_GATEWAY } from './infrastructure/gateways';
// Infrastructure - Repositories
import { PaymentErrorMapper } from './infrastructure/mappers';
import { PaymentKyselyRepository } from './infrastructure/repositories';
import { PaymentAggregateMapper } from './infrastructure/repositories/mappers/payment-aggregate.mapper';

// Infrastructure - Mappers

// ============================================================================
// HANDLER ARRAYS (for module providers and registration)
// ============================================================================

/**
 * Command handlers for Payment context
 */
const COMMAND_HANDLERS = [InitiatePaymentHandler, CompletePaymentHandler];

/**
 * Query handlers for Payment context
 */
const QUERY_HANDLERS = [GetPaymentStatusHandler];

/**
 * Event handlers for Payment context
 * NOTE: @EventHandler decorator enables auto-discovery by VytchesDDD
 */
const EVENT_HANDLERS = [PaymentCompletedHandler, PaymentAuditHandler];

// ============================================================================
// MODULE DEFINITION
// ============================================================================

@Module({
  imports: [],
  providers: [
    // =========================================================================
    // Per-Context Event Persistence (TS-SHARED-PGUTIL-001)
    // =========================================================================
    // Override global IEventPersistenceHandler with Payment-specific configuration
    // Uses 'payment_aggregate_versions' table to avoid PRIMARY KEY collisions with other contexts
    // DDD Pattern: Each bounded context manages its own aggregate versions independently
    {
      provide: EVENT_PERSISTENCE_HANDLER_TOKEN,
      useFactory: (
        txHost: TransactionHost<TransactionalAdapterKysely<Database>>,
        requestContext: RequestContextService,
        metadataStandards: MetadataStandardsService
      ) => {
        return new KyselyEventPersistenceHandler(
          txHost,
          requestContext,
          metadataStandards,
          { versionsTableName: 'payment_aggregate_versions' } // Payment context uses payment_aggregate_versions table
        );
      },
      inject: [TransactionHost, RequestContextService, MetadataStandardsService],
    },

    // ========================================
    // Repository Provider
    // ========================================
    {
      provide: PAYMENT_REPOSITORY,
      useClass: PaymentKyselyRepository,
    },

    // ========================================
    // Gateway Provider (TS-TOKEN-TOPUP-001 Faza 0, DEC2/DEC20: NullPaymentGateway
    // is the only PAYMENT_GATEWAY binding until a real PayU adapter exists —
    // see PaymentModule.onModuleInit() for the fail-fast productionSafe assertion)
    // ========================================
    {
      provide: PAYMENT_GATEWAY,
      useClass: NullPaymentGateway,
    },

    // ========================================
    // Mappers
    // ========================================
    PaymentAggregateMapper,
    PaymentErrorMapper,

    // ========================================
    // Command Handlers
    // ========================================
    ...COMMAND_HANDLERS,

    // ========================================
    // Query Handlers
    // ========================================
    ...QUERY_HANDLERS,

    // ========================================
    // Event Handlers (auto-discovered by VytchesDDD)
    // ========================================
    ...EVENT_HANDLERS,
  ],
  exports: [
    // Export for cross-context usage (e.g., NeighborhoodEconomyModule)
    PAYMENT_REPOSITORY,
    PAYMENT_GATEWAY,
  ],
})
export class PaymentModule implements OnModuleInit {
  constructor(
    @Inject(PaymentErrorMapper) private readonly paymentErrorMapper: PaymentErrorMapper,
    @Inject(PAYMENT_GATEWAY) private readonly paymentGateway: IPaymentGateway
  ) {}

  /**
   * Register error mapper and other module-level initialization.
   *
   * Command/Query handlers auto-registered via @CommandHandler/@QueryHandler decorators
   */
  onModuleInit() {
    // Command/Query handlers auto-registered via @CommandHandler/@QueryHandler decorators

    // ========================================
    // Register Error Mapper
    // ========================================
    this.registerErrorMapper();

    // ========================================
    // Bootstrap-time fail-fast: PAYMENT_GATEWAY must be production-safe
    // (TS-TOKEN-TOPUP-001 Faza 0, DEC20). This is NOT a domain/Result path —
    // an unsafe gateway binding must block application startup entirely, so a
    // thrown Error (not Result.fail) is intentional here.
    // ========================================
    this.assertPaymentGatewayIsProductionSafe();

    console.log('[PaymentModule] Initialized with handlers and error mapper');
  }

  /**
   * Fail fast if the bound PAYMENT_GATEWAY is not production-safe.
   *
   * `NullPaymentGateway` (`capabilities.productionSafe === true`) is the only
   * binding today — every operation fails closed, so sales are effectively
   * disabled until a real, production-safe PayU adapter is wired in. Logs a
   * single explicit line describing which gateway is bound and whether sales
   * are effectively enabled, so this state is visible at every boot, not just
   * discoverable by reading source.
   */
  private assertPaymentGatewayIsProductionSafe(): void {
    if (!this.paymentGateway.capabilities.productionSafe) {
      throw new Error(
        '[PaymentModule] PAYMENT_GATEWAY binding is not production-safe. Refusing to start.'
      );
    }

    const isSalesEnabled =
      this.paymentGateway.capabilities.productionSafe &&
      !(this.paymentGateway instanceof NullPaymentGateway);

    console.log(
      `[PaymentModule] PAYMENT_GATEWAY bound: ${this.paymentGateway.constructor.name} ` +
        `(productionSafe=${this.paymentGateway.capabilities.productionSafe}, ` +
        `salesEnabled=${isSalesEnabled})`
    );
  }

  /**
   * Register error mapper with global error mapping registry
   *
   * Pattern: TS-INFRA-001 (standardized error mapper registration)
   * 1. Try getInstance() for immediate registration if registry exists
   * 2. Fall back to DomainErrorRegistryService for deferred registration
   */
  private registerErrorMapper(): void {
    const errorRegistry = ErrorMappingRegistry.getInstance();
    if (errorRegistry) {
      errorRegistry.registerMapper(this.paymentErrorMapper);
    } else {
      // ErrorMappingRegistry not yet instantiated - use deferred registration
      // This can happen if PaymentModule initializes before ResponseModule
      DomainErrorRegistryService.registerMapper(this.paymentErrorMapper);
    }
  }
}

1	/**
2	 * @fileoverview SMSAPI IP Guard
3	 *
4	 * Restricts the DLR (Delivery Report) callback endpoint to known SMSAPI.pl
5	 * IP ranges. Prevents unauthorized parties from injecting fake delivery reports.
6	 *
7	 * Security design:
8	 *   - Uses SecureIPExtractorService to resist X-Forwarded-For spoofing
9	 *   - Degraded mode: empty callbackIpRanges list → ALLOW (log warn, do not block)
10	 *     (prevents lockout if config is missing — DLR loss is preferable to endpoint break)
11	 *   - Unknown IP → 403 Forbidden
12	 *
13	 * CIDR support: Only /24 networks are supported (sufficient for SMSAPI.pl ranges).
14	 * The check compares the first 3 octets of IPv4 addresses.
15	 *
16	 * @see TS-SMS-002
17	 * @see https://www.smsapi.pl/rest-api/#dlr (SMSAPI IP ranges)
18	 */
19	
20	import {
21	  type CanActivate,
22	  type ExecutionContext,
23	  ForbiddenException,
24	  Inject,
25	  Injectable,
26	} from '@nestjs/common';
27	import type { Request } from 'express';
28	
29	import { ConfigService } from '@shared/config/config.service';
30	import { LOGGER_SERVICE, type ILoggerService } from '@shared/infrastructure/logging';
31	import { SecureIPExtractorService } from '@shared/security/services/secure-ip-extractor.service';
32	
33	@Injectable()
34	export class SmsApiIpGuard implements CanActivate {
35	  private readonly logger: ILoggerService;
36	
37	  constructor(
38	    @Inject(ConfigService) private readonly config: ConfigService,
39	    @Inject(SecureIPExtractorService)
40	    private readonly ipExtractor: SecureIPExtractorService,
41	    @Inject(LOGGER_SERVICE) logger: ILoggerService
42	  ) {
43	    this.logger = logger.createChildLogger(SmsApiIpGuard.name);
44	  }
45	
46	  canActivate(context: ExecutionContext): boolean {
47	    const request = context.switchToHttp().getRequest<Request>();
48	    const ipResult = this.ipExtractor.extractSecureClientIP(request);
49	    const clientIp = ipResult.clientIP;
50	
51	    const ranges: string[] = this.config.get<string[]>('sms.smsapi.callbackIpRanges') ?? [];
52	
53	    // Degraded mode — no ranges configured
54	    // Production: fail-closed (fake DLRs are preferable to silently accepting all)
55	    // Dev/test: pass-through (avoids requiring config for local runs)
56	    if (ranges.length === 0) {
57	      const isProduction = process.env['NODE_ENV'] === 'production';
58	      this.logger.warn(
59	        'SMSAPI_CALLBACK_IP_RANGES not configured — DLR guard in pass-through mode',
60	        {
61	          operation: 'DlrIpGuardDegradedMode',
62	          environment: process.env['NODE_ENV'],
63	        }
64	      );
65	      if (isProduction) {
66	        throw new ForbiddenException('Access denied');
67	      }
68	      return true;
69	    }
70	
71	    const allowed = ranges.some(cidr => this.isInCidr24(clientIp, cidr));
72	
73	    if (!allowed) {
74	      this.logger.warn('DLR callback from unknown IP — request rejected', {
75	        operation: 'DlrIpGuardBlocked',
76	        ipPrefix: this.maskIp(clientIp),
77	      });
78	      throw new ForbiddenException('Access denied');
79	    }
80	
81	    return true;
82	  }
83	
84	  /**
85	   * Check if an IPv4 address is within a /24 CIDR block.
86	   * Strips port suffix if present (e.g., "::ffff:1.2.3.4").
87	   * Returns false for IPv6 addresses that don't map to IPv4.
88	   */
89	  private isInCidr24(ip: string, cidr: string): boolean {
90	    // Normalize IPv4-mapped IPv6 addresses (::ffff:1.2.3.4)
91	    const normalizedIp = ip.replace(/^::ffff:/i, '');
92	
93	    // Parse the network address from CIDR notation
94	    const [networkAddress] = cidr.split('/');
95	    if (!networkAddress) return false;
96	
97	    const ipParts = normalizedIp.split('.');
98	    const netParts = networkAddress.split('.');
99	
100	    if (ipParts.length !== 4 || netParts.length !== 4) return false;
101	
102	    // For /24: compare first 3 octets
103	    return ipParts[0] === netParts[0] && ipParts[1] === netParts[1] && ipParts[2] === netParts[2];
104	  }
105	
106	  /** Mask IP to first 2 octets for safe logging */
107	  private maskIp(ip: string): string {
108	    const parts = ip.replace(/^::ffff:/i, '').split('.');
109	    if (parts.length >= 2) {
110	      return `${parts[0]}.${parts[1]}.x.x`;
111	    }
112	    return '[masked]';
113	  }
114	}
