/**
 * Null Payment Gateway Service
 *
 * TS-TOKEN-TOPUP-001 Faza 0 (DEC2, DEC20) — structural replacement for the
 * removed `MockPayUPaymentGatewayService`.
 *
 * `MockPayUPaymentGatewayService.verifyWebhookSignature()` used to return
 * `true` unconditionally, which made `POST /api/payments/webhooks/payu` a
 * public, unauthenticated "set payment to COMPLETED" switch on production
 * (`TM-TOPUP-S1`, DREAD 14). `NullPaymentGateway` closes that hole
 * structurally instead of behind a guard: every operation fails, so there is
 * no code path left that can fabricate a successful payment or a valid
 * signature.
 *
 * This is the default (and, until a real gateway adapter exists, the ONLY)
 * `PAYMENT_GATEWAY` binding in every environment, including production
 * (`capabilities.productionSafe === true` — see
 * `PaymentModule.onModuleInit()`). A real PayU adapter is explicitly out of
 * scope for TS-TOKEN-TOPUP-001 (analysis DEC "Z5") — this task builds the
 * domain path only, with the money-taking entry point closed.
 *
 * @module Payment/Infrastructure/Gateways
 * @since TS-TOKEN-TOPUP-001
 */

import { Injectable } from '@nestjs/common';
import { Result } from '@vytches/ddd';

import { PaymentsNotAvailableError } from '../../domain/errors/payment.errors';
import type {
  CreatePaymentIntentParams,
  CreatePaymentIntentResult,
  IPaymentGateway,
  PaymentGatewayCapabilities,
} from '../../domain/ports/payment-gateway.port';

@Injectable()
export class NullPaymentGateway implements IPaymentGateway {
  readonly capabilities: PaymentGatewayCapabilities = { productionSafe: true };

  /**
   * Always fails — there is no gateway to create a payment intent with.
   *
   * @param _params - unused
   */
  async createPaymentIntent(
    _params: CreatePaymentIntentParams
  ): Promise<Result<CreatePaymentIntentResult, Error>> {
    return Result.fail(new PaymentsNotAvailableError());
  }

  /**
   * Fails closed — always `false`.
   *
   * No real gateway is configured, so no signature presented to this binding
   * can ever be genuine. Returning `false` (never throwing) lets the calling
   * webhook controller apply its own "invalid signature" response (400 +
   * alert), the same path forged notifications take.
   *
   * @param _payload - unused
   * @param _signature - unused
   */
  verifyWebhookSignature(_payload: string, _signature: string): boolean {
    return false;
  }

  /**
   * Always fails — there is no gateway to query a status from.
   *
   * @param _externalPaymentId - unused
   */
  async getPaymentStatus(
    _externalPaymentId: string
  ): Promise<Result<'PENDING' | 'COMPLETED' | 'FAILED', Error>> {
    return Result.fail(new PaymentsNotAvailableError());
  }
}

