/**
 * Migration 266: payment_gateway_raw_notifications table
 * (TS-TOKEN-TOPUP-001 Faza 0, część A2)
 *
 * Durable evidence trail for every PayU webhook notification hitting
 * `POST /api/payments/webhooks/payu`, written BEFORE the rest of the webhook
 * handling flow runs (see `PaymentsWebhookController.handlePayuWebhook()`).
 * This is separate from — and does not replace — the money-path outbox row
 * written by `PaymentCompletedHandler` (see BR-PAY-OUTBOX-ATOMIC-001); this
 * table exists to forensically reconstruct what PayU actually sent us,
 * independent of whether the notification was ultimately accepted.
 *
 * Columns:
 *   - payload_sha256: sha256 hex of the raw (pre-parse) webhook body — lets
 *     us detect byte-identical retries/replays without storing the raw body.
 *   - payload_redacted: jsonb allowlist projection of the PayU payload
 *     (orderId, extOrderId, status, totalAmount, currencyCode,
 *     localReceiptDateTime ONLY — see
 *     `payment-webhook-redaction.util.ts#toRedactedPayload`). Deliberately
 *     excludes `order.customerIp` (PII) and `properties[]` (arbitrary
 *     provider-supplied key/value pairs).
 *   - headers_redacted: jsonb, exactly the 8 fields produced by
 *     `toRedactedHeaders()` — an explicit allowlist, not a blocklist, so an
 *     unrecognized header (cookie, authorization, x-forwarded-for, ...) can
 *     never leak into storage.
 *   - signature_valid: whether `IPaymentGateway.verifyWebhookSignature()`
 *     accepted this notification.
 *   - source_ip_hash / source_ip_allowlisted / request_id: derived,
 *     non-reversible identifiers — `source_ip_hash` is
 *     `hashIdentifier(clientIp)` (ANONYMIZATION_SALT), never a raw IP
 *     (SI5). `source_ip_allowlisted` defaults to `false` — see GAP note in
 *     `payment-webhook-redaction.util.ts#isSourceIpAllowlisted`: no PayU
 *     source-IP allowlist exists in docs/security/rules/ yet, so this column
 *     is written from day one but is not yet meaningfully populated.
 *
 * DEC21 (sampling for signature_valid=false): a full row per FAILED
 * (unverified-signature) request would let an attacker cheaply flood this
 * table. Instead, failed attempts are aggregated one row per
 * (source_ip_hash, hour_bucket) with `attempt_count` incremented via
 * `ON CONFLICT ... DO UPDATE` against the partial unique index below. Only
 * VERIFIED notifications (signature_valid = true) get a full row per
 * request. `hour_bucket` is `date_trunc('hour', received_at)`, computed by
 * the repository (not a generated column) so the application controls the
 * exact bucket boundary used for both the INSERT and the upsert conflict
 * target.
 *
 * Partial index `payment_gateway_raw_notifications_failed_ip_hour_uq` is
 * simultaneously: (a) the DEC21 aggregation key (UNIQUE) and (b) a query
 * accelerator scoped to the `signature_valid = false` rows a security
 * reviewer actually cares about — this is the "Partial index WHERE
 * signature_valid = false" required by the task, not a separate index.
 *
 * Retention/cron cleanup of this table is explicitly OUT of scope here (see
 * task unit A3) — this migration only creates the table + index.
 *
 * @module Shared/Database/Migrations
 * @see src/contexts/payment/infrastructure/webhooks/payment-webhook-redaction.util.ts
 * @see src/contexts/payment/infrastructure/repositories/payment-gateway-raw-notification-kysely.repository.ts
 * @see src/app/api/payments/payments-webhook.controller.ts
 * @see src/contexts/payment/BUSINESS_RULES.yaml (BR-PAY-RAWNOTIF-WRITE-SAMPLING-001)
 */

import { createHash } from 'crypto';

import type { Kysely } from 'kysely';
import { sql } from 'kysely';

import type { Database } from '../types/database.types';

import type { Migration } from './types';

export default class AddPaymentGatewayRawNotifications implements Migration {
  readonly id = '266_add_payment_gateway_raw_notifications';
  readonly name =
    'Create payment_gateway_raw_notifications table — redacted PayU webhook evidence trail with DEC21 sampling for failed-signature attempts (TS-TOKEN-TOPUP-001 Faza 0, część A2)';

  readonly version = 266;
  readonly environments = ['development', 'staging', 'production', 'test'];

  async up(db: Kysely<Database>): Promise<void> {
    await sql`SET LOCAL lock_timeout = '3s'`.execute(db);

    await db.schema
      .createTable('payment_gateway_raw_notifications')
      .ifNotExists()
      .addColumn('id', 'uuid', col => col.primaryKey().defaultTo(sql`gen_random_uuid()`))
      .addColumn('payload_sha256', 'varchar(64)', col => col.notNull())
      .addColumn('payload_redacted', 'jsonb', col => col.notNull())
      .addColumn('headers_redacted', 'jsonb', col => col.notNull())
      .addColumn('signature_valid', 'boolean', col => col.notNull())
      .addColumn('received_at', 'timestamptz', col => col.notNull().defaultTo(sql`now()`))
      // DEC21: truncated-to-the-hour bucket used as (part of) the sampling
      // aggregation key for signature_valid = false rows. Computed by the
      // repository (date_trunc('hour', receivedAt)) at write time, not a
      // Postgres GENERATED column, so the app fully controls the boundary.
      .addColumn('hour_bucket', 'timestamptz', col => col.notNull())
      .addColumn('source_ip_hash', 'varchar(64)', col => col.notNull())
      .addColumn('source_ip_allowlisted', 'boolean', col => col.notNull().defaultTo(false))
      .addColumn('request_id', 'varchar(128)')
      // DEC21: number of failed-signature attempts folded into this row.
      // Always 1 for signature_valid = true rows (one row per request).
      .addColumn('attempt_count', 'integer', col => col.notNull().defaultTo(1))
      .execute();

    // DEC21 aggregation key + query accelerator: one row per
    // (source_ip_hash, hour_bucket) among FAILED-signature notifications
    // only. ON CONFLICT (source_ip_hash, hour_bucket) WHERE signature_valid
    // = false is the upsert target used by
    // PaymentGatewayRawNotificationKyselyRepository.recordFailedSignatureSample().
    await sql`
      CREATE UNIQUE INDEX IF NOT EXISTS payment_gateway_raw_notifications_failed_ip_hour_uq
        ON payment_gateway_raw_notifications (source_ip_hash, hour_bucket)
        WHERE signature_valid = false
    `.execute(db);
  }

  async down(db: Kysely<Database>): Promise<void> {
    await sql`SET LOCAL lock_timeout = '3s'`.execute(db);

    await db.schema.dropTable('payment_gateway_raw_notifications').ifExists().execute();
  }

  getChecksum(): string {
    const content = `${this.id}-${this.name}-${this.version}-payment_gateway_raw_notifications-signature_valid-source_ip_hash`;
    return createHash('sha256').update(content).digest('hex');
  }
}

