/**
 * @fileoverview PayU Webhook Redaction Utilities
 *
 * Pure, deterministic helpers that turn a raw PayU webhook request (payload +
 * HTTP headers) into the redacted shapes persisted by
 * `payment_gateway_raw_notifications` (Migration 266,
 * TS-TOKEN-TOPUP-001 Faza 0, część A2). No I/O, no NestJS DI — safe to unit
 * test directly (see the frozen-key-set guardian in
 * `__tests__/payment-webhook-redaction.util.guardian.spec.ts`, owned by
 * @test-implementer).
 *
 * Two independent allowlists live here, both explicit (never a blocklist):
 *   - `toRedactedPayload()` — payload field allowlist (ADR-0021 format
 *     validation happens upstream via `payuWebhookPayloadSchema`; this is a
 *     SEPARATE, narrower allowlist for what is safe to durably persist).
 *   - `toRedactedHeaders()` — header field allowlist. Anything not in the
 *     frozen 8-field set (cookie, authorization, x-forwarded-for, ...) is
 *     silently dropped and only contributes to `unknownHeaderCount`, which is
 *     NOT persisted (keeps the stored shape exactly 8 keys) — it exists for
 *     the caller to log/alert on if desired.
 *
 * @module Payment/Infrastructure/Webhooks
 * @since TS-TOKEN-TOPUP-001
 */

import { createHash } from 'crypto';

import { hashIdentifier } from '@shared/utils/crypto.utils';
import type { PayuWebhookPayload } from '@shared/validation/schemas/payments';

// ============================================================================
// PAYLOAD REDACTION
// ============================================================================

/**
 * Allowlisted, persisted projection of a PayU webhook payload.
 *
 * Deliberately excludes `order.customerIp` (PII — the source IP is captured
 * separately, hashed, as `source_ip_hash`) and `properties[]` (arbitrary
 * provider-supplied key/value pairs with no fixed schema — cannot be safely
 * allowlisted field-by-field).
 */
export interface RedactedWebhookPayload {
  readonly orderId: string;
  readonly extOrderId: string | null;
  readonly status: string;
  readonly totalAmount: string | null;
  readonly currencyCode: string | null;
  readonly localReceiptDateTime: string | null;
}

/**
 * Project a validated PayU webhook payload down to the allowlisted fields
 * safe to persist in `payment_gateway_raw_notifications.payload_redacted`.
 *
 * @param payload - already Zod-validated (`payuWebhookPayloadSchema`) payload
 */
export function toRedactedPayload(payload: PayuWebhookPayload): RedactedWebhookPayload {
  return {
    orderId: payload.order.orderId,
    extOrderId: payload.order.extOrderId ?? null,
    status: payload.order.status,
    totalAmount: payload.order.totalAmount ?? null,
    currencyCode: payload.order.currencyCode ?? null,
    localReceiptDateTime: payload.localReceiptDateTime ?? null,
  };
}

/**
 * sha256 hex digest of the raw (pre-parse) webhook body.
 *
 * Stored as `payload_sha256` — lets us detect byte-identical retries/replays
 * without storing the raw body itself (which could contain
 * `order.customerIp`/`properties[]`).
 */
export function computePayloadSha256(rawBody: string): string {
  return createHash('sha256').update(rawBody).digest('hex');
}

// ============================================================================
// HEADER REDACTION
// ============================================================================

/**
 * Exactly the 8 fields persisted in
 * `payment_gateway_raw_notifications.headers_redacted`. Frozen set — do not
 * add fields without updating the guardian test and this docblock together.
 */
export interface RedactedWebhookHeaders {
  readonly openpayu_sig_sender: string | null;
  readonly openpayu_sig_algorithm: string | null;
  readonly openpayu_sig_value: string | null;
  readonly openpayu_sig_content: string | null;
  readonly content_type: string | null;
  readonly content_length: string | null;
  readonly user_agent: string | null;
  readonly provider_date: string | null;
}

/** Node/Express normalizes incoming header names to lowercase. */
export type IncomingHeadersLike = Record<string, string | string[] | undefined>;

const USER_AGENT_MAX_LENGTH = 256;

/**
 * The 8 raw header names this allowlist reads from. Everything else on the
 * request (cookie, authorization, x-forwarded-for, ...) is ignored and only
 * counted in `unknownHeaderCount`.
 *
 * `openpayu-signature` is PayU's single composite header, formatted as
 * semicolon-separated `key=value` pairs (`signature=...;algorithm=...;
 * sender=...;content=DOCUMENT`) — parsed into 4 of the 8 output fields below.
 */
const KNOWN_RAW_HEADER_NAMES = new Set([
  'openpayu-signature',
  'content-type',
  'content-length',
  'user-agent',
  // GAP: no confirmed PayU-specific date header name exists in this repo's
  // docs/security/rules/ today. `date` is the standard HTTP response/request
  // date header and the closest available signal for `provider_date` — flag
  // for confirmation against PayU's actual notification headers before
  // relying on this field for anything beyond forensics.
  'date',
]);

function firstValue(value: string | string[] | undefined): string | null {
  if (value === undefined) return null;
  return Array.isArray(value) ? (value[0] ?? null) : value;
}

/**
 * Parse PayU's composite `OpenPayu-Signature` header
 * (`signature=...;algorithm=...;sender=...;content=DOCUMENT`) into its
 * components. Unknown/missing components are `null`, never thrown.
 */
function parseOpenPayuSignatureHeader(headerValue: string | null): {
  sender: string | null;
  algorithm: string | null;
  value: string | null;
  content: string | null;
} {
  if (!headerValue) {
    return { sender: null, algorithm: null, value: null, content: null };
  }

  const parts = new Map<string, string>();
  for (const segment of headerValue.split(';')) {
    const eqIndex = segment.indexOf('=');
    if (eqIndex === -1) continue;
    const key = segment.slice(0, eqIndex).trim().toLowerCase();
    const val = segment.slice(eqIndex + 1).trim();
    if (key) parts.set(key, val);
  }

  return {
    sender: parts.get('sender') ?? null,
    algorithm: parts.get('algorithm') ?? null,
    value: parts.get('signature') ?? null,
    content: parts.get('content') ?? null,
  };
}

/**
 * Redact incoming HTTP headers down to the frozen 8-field allowlist.
 *
 * @param headers - raw `req.headers` (Express normalizes names to lowercase)
 * @returns `headers` — exactly the 8 allowlisted fields (persisted as-is to
 *   `headers_redacted`) — and `unknownHeaderCount` — number of header names
 *   NOT in the allowlist, for the caller to log/alert on; deliberately NOT
 *   included in `headers` itself (would break the frozen 8-key contract).
 */
export function toRedactedHeaders(headers: IncomingHeadersLike): {
  headers: RedactedWebhookHeaders;
  unknownHeaderCount: number;
} {
  const sig = parseOpenPayuSignatureHeader(firstValue(headers['openpayu-signature']));
  const userAgent = firstValue(headers['user-agent']);

  const redacted: RedactedWebhookHeaders = {
    openpayu_sig_sender: sig.sender,
    openpayu_sig_algorithm: sig.algorithm,
    openpayu_sig_value: sig.value,
    openpayu_sig_content: sig.content,
    content_type: firstValue(headers['content-type']),
    content_length: firstValue(headers['content-length']),
    user_agent: userAgent ? userAgent.slice(0, USER_AGENT_MAX_LENGTH) : null,
    provider_date: firstValue(headers['date']),
  };

  const unknownHeaderCount = Object.keys(headers).filter(
    name => !KNOWN_RAW_HEADER_NAMES.has(name.toLowerCase())
  ).length;

  return { headers: redacted, unknownHeaderCount };
}

// ============================================================================
// SOURCE IP
// ============================================================================

/**
 * `source_ip_hash` — `hashIdentifier(clientIp)` (ANONYMIZATION_SALT), never a
 * raw IP address (SI5). `clientIp` MUST come from
 * `SecureIPExtractorService.extractSecureClientIP()` (spoofing-resistant),
 * not read directly off a header — `hashIdentifier()` only does the hashing
 * half of this, extraction is a separate, prior step done by the caller.
 */
export function hashSourceIp(clientIp: string): string {
  return hashIdentifier(clientIp);
}

/**
 * Whether `clientIp` falls within a configured PayU webhook source-IP
 * allowlist (CIDR /24 match, same technique as
 * `SmsApiIpGuard.isInCidr24()` — TS-SMS-002).
 *
 * GAP (TS-TOKEN-TOPUP-001 Faza 0, część A2): no PayU webhook source-IP
 * allowlist exists in `docs/security/rules/` or `ConfigService` today — this
 * is a security parameter that must be sourced from
 * `docs/security/rules/rate-limiting-abuse.md` (or a decision from
 * @security-privacy-architect), not invented here. Until that parameter
 * exists, callers pass `[]` and every request is `source_ip_allowlisted:
 * false`. The column is written from day one so no backfill is needed once
 * the range list lands.
 */
export function isSourceIpAllowlisted(clientIp: string, allowlistRangesCidr24: readonly string[]): boolean {
  if (allowlistRangesCidr24.length === 0) return false;

  const normalizedIp = clientIp.replace(/^::ffff:/i, '');
  const ipParts = normalizedIp.split('.');
  if (ipParts.length !== 4) return false;

  return allowlistRangesCidr24.some(cidr => {
    const [networkAddress] = cidr.split('/');
    if (!networkAddress) return false;
    const netParts = networkAddress.split('.');
    if (netParts.length !== 4) return false;
    return ipParts[0] === netParts[0] && ipParts[1] === netParts[1] && ipParts[2] === netParts[2];
  });
}

// ============================================================================
// HOUR BUCKET (DEC21 sampling key)
// ============================================================================

/**
 * Truncate a timestamp to the start of its hour (UTC) — the `hour_bucket`
 * half of the DEC21 `(source_ip_hash, hour_bucket)` sampling key for
 * `signature_valid = false` rows.
 */
export function toHourBucket(receivedAt: Date): Date {
  const bucket = new Date(receivedAt);
  bucket.setUTCMinutes(0, 0, 0);
  return bucket;
}

