/**
 * @fileoverview PaymentGatewayRawNotificationKyselyRepository
 *
 * Query-side (no aggregate) repository for
 * `payment_gateway_raw_notifications` — the redacted PayU webhook evidence
 * trail (Migration 266, TS-TOKEN-TOPUP-001 Faza 0, część A2).
 *
 * RP12-EXCEPTION: `payment_gateway_raw_notifications` has no aggregate/domain
 * port — it is a pure infrastructure evidence log, not a DDD aggregate. This
 * repository injects `DATABASE_TOKEN` directly (no `BaseKyselyRepository`,
 * no `LOGGER_SERVICE` — console.warn is the established convention for
 * repositories in this repo).
 *
 * Two write paths, per DEC21 (see BR-PAY-RAWNOTIF-WRITE-SAMPLING-001):
 *   - `recordVerifiedNotification()` — one full row per verified
 *     (`signature_valid = true`) request.
 *   - `recordFailedSignatureSample()` — sampled: one aggregated row per
 *     (source_ip_hash, hour_bucket) among unverified requests, upserted via
 *     `ON CONFLICT ... DO UPDATE` incrementing `attempt_count` against the
 *     partial unique index created by Migration 266.
 *
 * Both methods are best-effort/fire-and-forget on failure (catch +
 * console.warn, never throw) — the same precedent already used for
 * non-critical audit writes in this codebase (see
 * `SecurityOperationKyselyRepository.auditLockAcquisition/auditLockRelease`).
 * A raw-notification write failing must never block the webhook response or
 * (for verified notifications) payment completion — that would make this
 * evidence trail a new availability dependency for the money path, which is
 * a bigger design decision than this task authorizes (see the deferred TODO
 * in `PaymentsWebhookController` re: gating 2xx on durable persistence).
 *
 * @module Payment/Infrastructure/Repositories
 * @since TS-TOKEN-TOPUP-001
 */

import { Inject, Injectable } from '@nestjs/common';
import type { Kysely } from 'kysely';
import { sql } from 'kysely';

import type { Database } from '@shared/database/types/database.types';
import { DATABASE_TOKEN } from '@shared/database/tokens';

import type { RedactedWebhookHeaders, RedactedWebhookPayload } from '../webhooks/payment-webhook-redaction.util';
import { toHourBucket } from '../webhooks/payment-webhook-redaction.util';

export interface RecordVerifiedNotificationInput {
  readonly payloadSha256: string;
  readonly payloadRedacted: RedactedWebhookPayload;
  readonly headersRedacted: RedactedWebhookHeaders;
  readonly sourceIpHash: string;
  readonly sourceIpAllowlisted: boolean;
  readonly requestId: string | null;
  readonly receivedAt?: Date;
}

export interface RecordFailedSignatureSampleInput {
  readonly payloadSha256: string;
  readonly payloadRedacted: RedactedWebhookPayload;
  readonly headersRedacted: RedactedWebhookHeaders;
  readonly sourceIpHash: string;
  readonly sourceIpAllowlisted: boolean;
  readonly requestId: string | null;
  readonly receivedAt?: Date;
}

@Injectable()
export class PaymentGatewayRawNotificationKyselyRepository {
  // RP12-EXCEPTION: no aggregate/domain port exists for this table — pure
  // infrastructure evidence log, DATABASE_TOKEN injected directly.
  constructor(@Inject(DATABASE_TOKEN) private readonly db: Kysely<Database>) {}

  /**
   * Persist one full row for a notification whose signature was verified
   * (`signature_valid = true`). Never throws — logs and swallows on failure.
   */
  async recordVerifiedNotification(input: RecordVerifiedNotificationInput): Promise<void> {
    const receivedAt = input.receivedAt ?? new Date();

    try {
      await this.db
        .insertInto('payment_gateway_raw_notifications')
        .values({
          payload_sha256: input.payloadSha256,
          payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
          headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
          signature_valid: true,
          received_at: receivedAt,
          hour_bucket: toHourBucket(receivedAt),
          source_ip_hash: input.sourceIpHash,
          source_ip_allowlisted: input.sourceIpAllowlisted,
          request_id: input.requestId,
          attempt_count: 1,
        })
        .execute();
    } catch (error: unknown) {
      // Fire-and-forget: same precedent as SecurityOperationKyselyRepository
      // audit writes — a raw-notification write failure must not block
      // payment completion for a verified webhook.
      console.warn(
        '[PaymentGatewayRawNotificationKyselyRepository] Failed to record verified notification',
        { errorType: error instanceof Error ? error.constructor.name : typeof error }
      );
    }
  }

  /**
   * DEC21 sampling: upsert an aggregated row for a notification whose
   * signature FAILED verification (`signature_valid = false`), keyed on
   * (source_ip_hash, hour_bucket). Increments `attempt_count` and refreshes
   * the redacted payload/headers/received_at to the latest attempt on
   * conflict. Never throws — logs and swallows on failure.
   */
  async recordFailedSignatureSample(input: RecordFailedSignatureSampleInput): Promise<void> {
    const receivedAt = input.receivedAt ?? new Date();
    const hourBucket = toHourBucket(receivedAt);

    try {
      await this.db
        .insertInto('payment_gateway_raw_notifications')
        .values({
          payload_sha256: input.payloadSha256,
          payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
          headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
          signature_valid: false,
          received_at: receivedAt,
          hour_bucket: hourBucket,
          source_ip_hash: input.sourceIpHash,
          source_ip_allowlisted: input.sourceIpAllowlisted,
          request_id: input.requestId,
          attempt_count: 1,
        })
        .onConflict(oc =>
          oc
            .columns(['source_ip_hash', 'hour_bucket'])
            .where('signature_valid', '=', false)
            .doUpdateSet({
              received_at: receivedAt,
              request_id: input.requestId,
              payload_sha256: input.payloadSha256,
              payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
              headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
              source_ip_allowlisted: input.sourceIpAllowlisted,
              attempt_count: sql`payment_gateway_raw_notifications.attempt_count + 1`,
            })
        )
        .execute();
    } catch (error: unknown) {
      console.warn(
        '[PaymentGatewayRawNotificationKyselyRepository] Failed to record failed-signature sample',
        { errorType: error instanceof Error ? error.constructor.name : typeof error }
      );
    }
  }
}

